:root { color-scheme: light dark; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: rgb(246, 244, 239); color: rgb(39, 36, 31); }body { margin: 0px; }.webview-startup-shell { box-sizing: border-box; display: grid; min-height: 100vh; place-items: center; padding: 32px; background: radial-gradient(circle at center top, rgb(255, 250, 240) 0px, rgb(246, 244, 239) 48%, rgb(238, 235, 228) 100%); }.webview-startup-panel { box-sizing: border-box; width: min(680px, 100%); padding: 32px; border: 1px solid rgba(75, 66, 50, 0.16); border-radius: 18px; background: rgb(255, 253, 248); box-shadow: rgba(62, 51, 33, 0.1) 0px 18px 60px; }.webview-startup-mark { display: grid; width: 42px; height: 42px; place-items: center; border-radius: 12px; background: rgb(157, 122, 47); color: rgb(255, 255, 255); font-size: 13px; font-weight: 700; letter-spacing: 0.06em; }.webview-startup-panel h1 { margin: 22px 0px 10px; font-size: 22px; line-height: 1.35; }.webview-startup-panel p { margin: 8px 0px; line-height: 1.7; }.webview-startup-guidance { color: rgb(108, 98, 83); }.webview-startup-panel pre { max-height: 240px; margin: 22px 0px; padding: 14px; overflow: auto; border-radius: 10px; background: rgb(242, 238, 230); color: rgb(75, 68, 56); font: 12px / 1.55 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; white-space: pre-wrap; word-break: break-word; }.webview-startup-panel button { min-height: 36px; padding: 0px 16px; border: 0px; border-radius: 9px; background: rgb(157, 122, 47); color: rgb(255, 255, 255); cursor: pointer; font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-language-override: inherit; font-weight: 600; }.webview-startup-panel button:focus-visible { outline: rgb(157, 122, 47) solid 2px; outline-offset: 3px; }@media (prefers-color-scheme: dark) {
  :root { background: rgb(23, 22, 18); color: rgb(242, 238, 230); }
