  .webview-startup-panel { border-color: rgba(233, 211, 163, 0.14); background: rgb(33, 31, 26); box-shadow: rgba(0, 0, 0, 0.32) 0px 18px 60px; }
  .webview-startup-guidance { color: rgb(189, 180, 164); }
